for n,m in models.items():
 q={}
 for cn,c in m['cells'].items():
  if c['type']=='$dff':
   assert c['connections']['CLK']==m['ports']['SCK']['bits']
   assert int(c['parameters']['CLK_POLARITY'],2)==1
   for qb,db in zip(c['connections']['Q'],c['connections']['D']):
