  gn=ram['physical_cell'].removesuffix('_RAM')+'.RDATA_I'
  tn='regenerated.'+ram['decoded_instance']+'.RDATA_I'
  gb=models['gold']['netnames'][gn]['bits'];tb=models['gate']['netnames'][tn]['bits']
  assert len(gb)==len(tb)==16
  for i,(g,t) in enumerate(zip(gb,tb)):proposals.append((g,t,{'gold_name':gn,'gate_name':tn,'index':i,'bel':ram['bel']}))
mapping=[]
for g,t,evidence in proposals:
