 mapping.append({'gold_q':g,'gate_q':t,'correspondence_evidence':evidence,'gold_init':states['gold'][g]['init'],'gate_init':states['gate'][t]['init'],'gold_d':states['gold'][g]['d'],'gate_d':states['gate'][t]['d']})
assert len(mapping)==len(states['gold'])==len(states['gate'])==135
assert len({x['gold_q'] for x in mapping})==len({x['gate_q'] for x in mapping})==135
for n,m in models.items():
 c=copy.deepcopy(m)
 c['cells']={k:v for k,v in c['cells'].items() if v['type']!='$dff'}
 assert not any('ff' in v['type'] or 'mem' in v['type'] for v in c['cells'].values())
 for w in c['netnames'].values():w.get('attributes',{}).pop('init',None)
 for name,field,direction in [('state',n+'_q','input'),('next_state',n+'_d','output')]:
  bits=[x[field] for x in mapping]
