import json,copy,sys,hashlib,re
from run import ROOT,run
target=sys.argv[1];assert target in ['mapped','decoded']
label='transition_'+target
models={n:json.loads((ROOT/f).read_text())['modules']['protocol_dut'] for n,f in [('gold','gold_prepared.json'),('gate',('gate' if target=='mapped' else 'decoded')+'_prepared.json')]}
states={}
for n,m in models.items():
 q={}
 for cn,c in m['cells'].items():
