     v=w['attributes']['init'][::-1][i]
     assert q[b]['init'] in (None,v)
     q[b]['init']=v
 states[n]=q
proposals=[]
mapping_source=None
if target=='mapped':
 for g,q in states['gold'].items():
  candidates={}
  for nn,i in q['aliases']:
   w=models['gate']['netnames'].get(nn)
   if w and i<len(w['bits']) and w['bits'][i] in states['gate']:
    candidates.setdefault(w['bits'][i],[]).append((nn,i))
  assert len(candidates)==1,(g,candidates)
  t,aliases=next(iter(candidates.items()));proposals.append((g,t,aliases))
else:
 source=ROOT.parent.parent/'decode/physical_decoded_correspondence_v3.json'
 phys=json.loads(source.read_text());mapping_source={'path':str(source),'sha256':hashlib.sha256(source.read_bytes()).hexdigest()}
 assert phys['all_71_physical_flipflops_match_all_71_decoded_registers']
 assert phys['all_four_physical_RAMs_match_four_decoded_instances']
 mapped=json.loads((ROOT/'gate_prepared.json').read_text())['modules']['protocol_dut']
 mapped_relation=json.loads((ROOT/'transition_mapped_state_correspondence.json').read_text())
 mapped_to_gold={p['gate_q']:p['gold_q'] for p in mapped_relation['pairs']}
 def resolve_alias(a):
  if a in mapped['netnames']:return mapped['netnames'][a]['bits']
  if a.endswith('$SB_IO_OUT') and a.removesuffix('$SB_IO_OUT') in mapped['ports']:
   p=mapped['ports'][a.removesuffix('$SB_IO_OUT')];assert p['direction']=='output'
   return p['bits']
  match=re.fullmatch(r'(.*)\[(\d+)\]',a)
