   w=mapped['netnames'][match[1]];i=int(match[2])-w.get('offset',0)
   if w.get('upto',0):i=len(w['bits'])-1-i
   return [w['bits'][i]]
  return []
 for ff in phys['flipflops']:
  aliases=[a for rows in ff['ports']['O']['physical_net_aliases'].values() for a in rows]
  gb={mapped_to_gold[b] for a in aliases for b in resolve_alias(a) if b in mapped_to_gold}
  assert len(gb)==1,(ff['physical_cell'],aliases,gb)
  tw=models['gate']['netnames']['regenerated.'+ff['decoded_state']]['bits']
